def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    total = 0.0
    scale = 0.0
    for e, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        a = p.get(e) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = None
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif g == 18:
            q = 0.0
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        if q is not None:
            total += x * q
            scale += x * abs(q)
    return total / scale if scale > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    donor = 0.0
    acceptor = 0.0
    weight = 0.0
    for e, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        weight += x
        a = p.get(e) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = 0.0
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        donor += x * max(q, 0.0)
        acceptor += x * max(-q, 0.0)
    return min(donor, acceptor) / weight if weight > 0 else 0.0

