    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]
    near = [inf for k in range(n)]
    for bond in s.get('neighbors') or []:
        i, j = bond.get('i'), bond.get('j')
        d = bond.get('distance_A')
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:
            continue
        a, b = radii[i], radii[j]
        if a is None or b is None or not isfinite(a) or not isfinite(b) or a <= 0 or b <= 0:
            continue
        if d is not None and isfinite(d) and d > 0 and occ[j] > 0:
            near[i] = min(near[i], d / (a + b))
    ids = [i for i in range(n) if isfinite(near[i]) and isfinite(occ[i]) and occ[i] > 0]
    w = sum(occ[i] for i in ids)
    if w <= 0:
        return nan
    mean = sum(occ[i] * near[i] for i in ids) / w
    var = sum(occ[i] * (near[i] - mean) ** 2 for i in ids) / w
    return float(sqrt(max(0.0, var)) / mean) if mean > 0 else nan"},{"description":"Squared covalent-radius overlap summed over unique periodic contacts per atom.","name":"covalent_overlap_burden","source":"def feature(s):
