            continue
        if d is None or not isfinite(d) or d <= 0 or occ[i] <= 0 or occ[j] <= 0:
            continue
        total += occ[i] * occ[j] * max(0.0, 1.0 - d / (a + b)) ** 2
        valid += 1
    return float(0.5 * total / total_occ) if total_occ > 0 and valid > 0 else nan"},{"description":"Mean smooth coordination using a covalent-radius-scaled sixth-power exponential kernel.","name":"soft_coordination_mean","source":"def feature(s):
    s = s or {}
