    w = sum(occ[i] for i in ids)
    return float(sum(occ[i] * coord[i] for i in ids) / w) if w > 0 else nan"},{"description":"Occupancy-weighted coefficient of variation of smooth local coordination.","name":"soft_coordination_cv","source":"def feature(s):
