    var = sum(occ[i] * (coord[i] - mean) ** 2 for i in ids) / w
    return float(sqrt(max(0.0, var)) / mean) if mean > 0 else 0.0"},{"description":"Smooth heteroelement contact fraction relative to random mixing at the same composition.","name":"heterobond_enrichment","source":"def feature(s):
    s = s or {}
