            w = occ[i] * occ[j] * exp(-(x ** 6))
            total += w
            if sites[i].get('element') != sites[j].get('element'):
                unlike += w
    return float(unlike / (total * expected)) if total > 0 else nan"},{"description":"Per-atom short-range sum of squared electronegativity contrasts divided by distance.","name":"electronegativity_contact_density","source":"def feature(s):
    s = s or {}
