        o = 1.0 if o is None else o
        if e is not None and isfinite(e) and isfinite(o) and o > 0:
            total += o * e
            weight += o
    return float(total / (weight * v)) if weight > 0 else nan"},{"description":"Contact-weighted neutral-atom ionization-minus-affinity cost along increasing electronegativity.","name":"contact_charge_transfer_cost","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    p = [props.get(t.get('element')) or {} for t in sites]
