def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return nan
    return float(log1p(v))

def feature(s):
    s = s or {}
    v = s.get('density_g_cm3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('density_g_cm3')
    if v is None or not isfinite(v) or v <= 0:
        return nan
    return float(v)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return nan
    total = 0.0
    weight = 0.0
    for site in sites:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        o = site.get('occupancy')
        o = 1.0 if o is None else o
        if r is not None and isfinite(r) and r > 0 and isfinite(o) and o > 0:
            total += o * r ** 3
            weight += o
    return float(4.0 * pi * total / (3.0 * weight * v)) if weight > 0 else nan

def feature(s):
