    for b in bonds:
        i = b.get('i')
        d = b.get('distance_A')
        if i is not None and 0 <= i < n and d is not None and d > 0:
            near[i] = min(near[i], d)
    coord = [0.0 for t in sites]
    for b in bonds:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or d is None:
            continue
        if 0 <= i < n and 0 <= j < n and 0 < d <= 1.25 * near[i]:
            coord[i] += occ[j]
    weight = sum(occ)
    return float(sum(occ[i] * coord[i] for i in range(n)) / weight) if weight > 0 else 0.0"},{"description":"Site-to-site standard deviation of adaptive first-shell coordination.","name":"first_shell_coordination_dispersion","source":"def feature(s):
    s = s or {}
