    for b in bonds:
        i = b.get('i')
        d = b.get('distance_A')
        if i is not None and 0 <= i < n and d is not None and d > 0:
            near[i] = min(near[i], d)
    coord = [0.0 for t in sites]
    for b in bonds:
        i = b.get('i')
