        if 0 <= i < n and 0 <= j < n and 0 < d <= 1.25 * near[i]:
            coord[i] += occ[j]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * coord[i] for i in range(n)) / weight
    return float((sum(occ[i] * (coord[i] - mean) ** 2 for i in range(n)) / weight) ** 0.5)"},{"description":"Inverse-distance-weighted electronegativity difference across first-shell contacts.","name":"first_shell_electronegativity_contrast","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy')) if t.get('occupancy') is not None else 1.0 for t in sites]
    bonds = s.get('neighbors') or []
    near = [1000000.0 for t in sites]
    for b in bonds:
        i = b.get('i')
        d = b.get('distance_A')
        if i is not None and 0 <= i < n and d is not None and d > 0:
            near[i] = min(near[i], d)
    total = 0.0
    weight = 0.0
    for b in bonds:
        i = b.get('i')
