def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    return float(np.log1p(v))

def feature(s):
    s = s or {}
    comp = s.get('composition') or {}
    props = s.get('element_properties') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    total = 0.0
    weight = 0.0
    for el, x in comp.items():
        if x is None or x <= 0:
            continue
        r = (props.get(el) or {}).get('covalent_radius_A')
        if r is None or r <= 0:
            r = 1.3
        total += x * r ** 3
        weight += x
    return float(4.188790204786391 * total / (v * weight)) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = []
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    radii = [r if r is not None and r > 0 else 1.3 for r in radii]
    best = 1000000.0
