    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (counts[i] - mean) ** 2 for i in range(n)) / weight
    return sqrt(max(0.0, variance)) / mean"},{"description":"Mean within-site relative bond-length dispersion in the smooth first shell.","name":"shell_distance_dispersion","source":"def feature(s):
