            continue
        value = d / (radii[i] + radii[j])
        if best is None or value < best:
            best = value
    if best is None:
        return 0.0
    return float(best)"},{"description":"Occupancy-weighted squared covalent overlap summed over contacts per atom.","name":"covalent_compression_load","source":"def feature(s):
