        overlap = max(0.0, 1.0 - d / (radii[i] + radii[j]))
        total = total + weights[i] * weights[j] * overlap * overlap
    return float(total / (2.0 * atoms))"},{"description":"Mean occupancy-weighted coordination within 1.25 times each site's nearest distance.","name":"adaptive_coordination_mean","source":"def feature(s):
