            if d <= 1.25 * nearest[i]:
                counts[i] = counts[i] + weights[j]
    return float(sum(weights[i] * counts[i] for i in range(n)) / atoms)"},{"description":"Coefficient of variation of adaptive-shell coordination across occupied sites.","name":"adaptive_coordination_heterogeneity","source":"def feature(s):
