    if mean <= 0:
        return 0.0
    variance = sum(weights[i] * (counts[i] - mean) ** 2 for i in range(n)) / atoms
    return float(sqrt(max(0.0, variance)) / mean)"},{"description":"Coefficient of variation of site nearest-neighbor distances.","name":"nearest_distance_heterogeneity","source":"def feature(s):
