        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if d <= 1.25 * nearest[i] and en[i] is not None and en[j] is not None:
            w = weights[i] * weights[j]
            total = total + w * abs(en[i] - en[j])
            norm = norm + w
    if norm <= 0:
        return 0.0
    return float(total / norm)"},{"description":"Fraction of adaptive-shell contacts joining atoms of the same element.","name":"homonuclear_shell_fraction","source":"def feature(s):
    s = s or {}
