            continue
        if d <= 1.25 * nearest[i]:
            w = weights[i] * weights[j]
            total = total + w
            if sites[i].get('element') == sites[j].get('element'):
                same = same + w
    if total <= 0:
        return 0.0
    return float(same / total)"},{"description":"Close contacts between electronegative p-block atoms, counted per occupied atom.","name":"electronegative_network_contacts","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    properties = s.get('element_properties') or {}
    radii = [((properties.get(a.get('element')) or {}).get('covalent_radius_A') or 1.3) for a in sites]
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    eligible = [False for a in sites]
    for i in range(n):
        p = properties.get(sites[i].get('element')) or {}
        en = p.get('eneg')
        group = p.get('group')
        if en is not None and group is not None:
            eligible[i] = en >= 2.5 and group >= 14 and group <= 17
    atoms = sum(weights)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if eligible[i] and eligible[j] and d <= 1.2 * (radii[i] + radii[j]):
            total = total + weights[i] * weights[j]
    return float(total / (2.0 * atoms))"},{"description":"Mean within-site coefficient of variation of adaptive-shell bond lengths.","name":"local_bond_length_disorder","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    nearest = [7.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0 for a in sites]
    first = [0.0 for a in sites]
    second = [0.0 for a in sites]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if d <= 1.25 * nearest[i]:
            w = weights[j]
            counts[i] = counts[i] + w
            first[i] = first[i] + w * d
            second[i] = second[i] + w * d * d
    total = 0.0
    norm = 0.0
    for i in range(n):
        if counts[i] > 0 and first[i] > 0:
            mean = first[i] / counts[i]
            variance = max(0.0, second[i] / counts[i] - mean * mean)
            total = total + weights[i] * sqrt(variance) / mean
            norm = norm + weights[i]
    if norm <= 0:
        return 0.0
    return float(total / norm)"},{"description":"Mean squared resultant of first-shell unit bond vectors, measuring local directional imbalance.","name":"local_directional_imbalance","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    nearest = [7.0 for a in sites]
    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if i >= 0 and i < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    vx = [0.0 for a in sites]
    vy = [0.0 for a in sites]
    vz = [0.0 for a in sites]
    counts = [0.0 for a in sites]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if d > 1.25 * nearest[i]:
            continue
        a = sites[i].get('frac_coords')
        b = sites[j].get('frac_coords')
        image = edge.get('image')
        if a is None or b is None or image is None:
            continue
        f = [b[k] + image[k] - a[k] for k in range(3)]
        x = sum(f[k] * matrix[k][0] for k in range(3))
        y = sum(f[k] * matrix[k][1] for k in range(3))
        z = sum(f[k] * matrix[k][2] for k in range(3))
        length = sqrt(x * x + y * y + z * z)
        if length <= 0:
            continue
        w = weights[j]
        vx[i] = vx[i] + w * x / length
        vy[i] = vy[i] + w * y / length
        vz[i] = vz[i] + w * z / length
        counts[i] = counts[i] + w
    total = 0.0
    norm = 0.0
    for i in range(n):
        if counts[i] > 0:
            value = (vx[i] * vx[i] + vy[i] * vy[i] + vz[i] * vz[i]) / (counts[i] * counts[i])
            total = total + weights[i] * value
            norm = norm + weights[i]
    if norm <= 0:
        return 0.0
    return float(total / norm)"},{"description":"H3-convention valence electron count per cubic angstrom.","name":"valence_electron_density","source":"def feature(s):
    s = s or {}
    properties = s.get('element_properties') or {}
    total = 0.0
    atoms = 0.0
    for site in s.get('sites') or []:
        value = (properties.get(site.get('element')) or {}).get('valence_electrons')
        w = site.get('occupancy', 1.0) or 0.0
        atoms = atoms + w
        if value is not None:
            total = total + w * value
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * atoms
    if volume <= 0:
        return 0.0
    return float(total / volume)"},{"description":"Occupancy-weighted mean atomic chemical hardness, (ionization energy minus electron affinity)/2.","name":"mean_atomic_hardness","source":"def feature(s):
    s = s or {}
    properties = s.get('element_properties') or {}
    total = 0.0
    norm = 0.0
    for site in s.get('sites') or []:
        p = properties.get(site.get('element')) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is not None and affinity is not None:
            w = site.get('occupancy', 1.0) or 0.0
            total = total + w * (ionization - affinity) / 2.0
            norm = norm + w
    if norm <= 0:
        return 0.0
    return float(total / norm)"},{"description":"Occupancy-weighted standard deviation of Mulliken electronegativity in electronvolts.","name":"mulliken_electronegativity_spread","source":"def feature(s):
    s = s or {}
    properties = s.get('element_properties') or {}
    total = 0.0
    second = 0.0
    norm = 0.0
    for site in s.get('sites') or []:
        p = properties.get(site.get('element')) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is not None and affinity is not None:
            value = (ionization + affinity) / 2.0
            w = site.get('occupancy', 1.0) or 0.0
            total = total + w * value
            second = second + w * value * value
            norm = norm + w
    if norm <= 0:
        return 0.0
    mean = total / norm
    return float(sqrt(max(0.0, second / norm - mean * mean)))"},{"description":"Exponentially screened squared electronegativity contrast per atom over supplied periodic contacts.","name":"screened_polar_contact_strength","source":"def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    properties = s.get('element_properties') or {}
    en = [(properties.get(a.get('element')) or {}).get('eneg') for a in sites]
    radii = [((properties.get(a.get('element')) or {}).get('covalent_radius_A') or 1.3) for a in sites]
    weights = [(a.get('occupancy', 1.0) or 0.0) for a in sites]
    atoms = sum(weights)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if i < 0 or j < 0 or i >= n or j >= n or d is None or d <= 0:
            continue
        if en[i] is None or en[j] is None:
            continue
        contrast = en[i] - en[j]
        scale = radii[i] + radii[j]
        total = total + weights[i] * weights[j] * contrast * contrast * exp(-d / scale) / d
    return float(total / (2.0 * atoms))"},{"description":"Ratio of longest to shortest lattice vector.","name":"lattice_length_anisotropy","source":"def feature(s):
    s = s or {}
    lattice = s.get('lattice') or {}
    lengths = lattice.get('lengths_A')
    if lengths is None:
        matrix = lattice.get('matrix')
        if matrix is None:
            return 0.0
        lengths = [sqrt(sum(x * x for x in row)) for row in matrix]
    positive = [x for x in lengths if x is not None and x > 0]
    if not positive:
        return 0.0
    return float(max(positive) / min(positive))"}],"notes":"Adaptive shells use d ≤ 1.25 dmin within 6 Å; missing covalent radii use 1.3 Å; atomic-energy averages omit missing pairs, and screened polarity is not an electrostatic energy.","queries":[{"include_all":["O"],"include_any":["Re","Cu","Sc","Np","Mn"],"n":25,"n_elements":[3,7]},{"include_any":["C","N"],"n":25,"n_elements":[3,7]},{"exclude":["O","F","Cl","Br","I"],"include_any":["Pr","La","Sb","As","Ir","Au"],"n":25,"n_elements":[3,7]}],"rationale":"Replace rejected sources with standalone packing, local-bonding, and electronic descriptors; expand oxide, C/N, and oxygen-free pnictide/rare-metal coverage."}

