    values = [second[i] / nearest[i] - 1.0 for i in range(len(sites)) if nearest[i] > 0 and second[i] > 0]
    return float(sum(values) / len(values)) if values else 0.0"},{"description":"Mean occupancy-weighted radial neighbor sum with a 2-angstrom exponential decay length.","name":"screened_radial_environment","source":"def feature(s):
