            continue
        w = max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        occ = sites[j].get('occupancy')
        w *= 1.0 if occ is None else max(0.0, occ)
        if w <= 0:
            continue
        fi = sites[i].get('frac_coords')
        fj = sites[j].get('frac_coords')
        image = edge.get('image')
        if fi is None or fj is None or image is None:
            continue
        if len(fi) != 3 or len(fj) != 3 or len(image) != 3:
            continue
        a = fj[0] + image[0] - fi[0]
        b = fj[1] + image[1] - fi[1]
        c = fj[2] + image[2] - fi[2]
        x = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
        y = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
        z = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
        norm2 = x * x + y * y + z * z
        if norm2 <= 0:
            continue
        scale = w / norm2
        tensors[i][0] += scale * x * x
        tensors[i][1] += scale * y * y
        tensors[i][2] += scale * z * z
        tensors[i][3] += scale * x * y
        tensors[i][4] += scale * x * z
        tensors[i][5] += scale * y * z
        weights[i] += w
    total = 0.0
    valid = 0
    for i in range(len(sites)):
        if weights[i] > 0:
            t = tensors[i]
            trace2 = t[0] * t[0] + t[1] * t[1] + t[2] * t[2] + 2.0 * (t[3] * t[3] + t[4] * t[4] + t[5] * t[5])
            total += sqrt(max(0.0, 1.5 * trace2 / (weights[i] * weights[i]) - 0.5))
            valid += 1
    return float(total / valid) if valid else 0.0"}],"notes":"Covalent contacts and atomic transfer costs are geometric and isolated-atom proxies, not bond orders or crystal energies; neighborhoods are limited to 6 Å, and unavailable descriptor inputs return zero.","queries":[{"exclude":["O"],"include_any":["C","N","H"],"n":25},{"include_any":["F","Cl","Sb","Bi"],"n":25},{"include_any":["Th","U","Np","Pa","Be","Os","Re","Pd"],"n":25}],"rationale":"Structure-sensitive packing, coordination, bond polarity and angular order complement Magpie; queries broaden molecular, halide and sparsely represented heavy-element chemistry."}

