{"features":[{"description":"Smallest occupied-contact distance divided by the sum of covalent radii.","name":"minimum_reduced_contact","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    best = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0.0 and occ[i] * occ[j] > 0.0:
            value = d / (radii[i] + radii[j])
            if best == 0.0 or value < best:
                best = value
    return best"},{"description":"Smoothly cutoff-weighted covalent-overlap penalty per occupied atom.","name":"short_contact_compression","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and 0.0 < d < 6.0:
            overlap = max(0.0, (radii[i] + radii[j]) / d - 1.0)
            total += occ[i] * occ[j] * overlap ** 2 * (1.0 - d / 6.0) ** 2
    return total / (2.0 * max(sum(occ), 1e-12))"},{"description":"Inverse-distance, smoothly cutoff-weighted squared contact polarity per atom.","name":"screened_polarity_density","source":"def feature(s):
