                tensor[1] += w * v[1] * v[1]
                tensor[2] += w * v[2] * v[2]
                tensor[3] += w * v[0] * v[1]
                tensor[4] += w * v[0] * v[2]
                tensor[5] += w * v[1] * v[2]
    trace = tensor[0] + tensor[1] + tensor[2]
    if trace <= 0.0:
        return 0.0
    norm = sum(tensor[k] ** 2 for k in range(3)) + 2.0 * sum(tensor[k] ** 2 for k in range(3, 6))
    return max(0.0, min(1.0, 1.5 * norm / trace ** 2 - 0.5))"},{"description":"Site-averaged squared resultant of adaptive-shell unit bond vectors, measuring angular imbalance.","name":"local_angular_imbalance","source":"def feature(s):
