@13 n="nearest_shell_radial_distortion" d="Occupancy-weighted mean relative bond-length variance within 1.25 times each site's nearest-neighbor distance." B=1595
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    total = 0.0
    amount = 0.0
    for i in range(len(sites)):
        oi = sites[i].get('occupancy')
        oi = 1.0 if oi is None else max(0.0, oi)
        if oi <= 0:
            continue
        nearest = 0.0
        for edge in edges:
