                nearest = d
        if nearest <= 0:
            continue
        first = 0.0
        second = 0.0
        weight = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= len(sites) or d <= 0 or d > 1.25 * nearest:
