    total = sum(occ[i] * max(0.0, reference[i] - coordination[i]) for i in range(n) if reference[i] > 0)
    return float(total / amount) if amount > 0 else 0.0"},{"description":"Occupied-site fraction in finite components of the 1.20-radius-sum contact graph, detected using periodic-image winding.","name":"finite_contact_component_fraction","source":"def feature(s):
