    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    first = 0.0
    second = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        coordination = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d < 6.0:
