                coordination += occ[j] * max(0.0, 1.0 - u * u) ** 2
        first += occ[i] * coordination
        second += occ[i] * coordination * coordination
    weight = sum(occ)
    if weight <= 0.0 or first <= 0.0:
        return 0.0
    mean = first / weight
    variance = max(0.0, second / weight - mean * mean)
    return variance ** 0.5 / mean"},{"description":"Soft-contact-weighted coefficient of variation of distances normalized by covalent-radius sums.","name":"reduced_contact_length_dispersion","source":"def feature(s):
