            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
            total += w
            if sites[i].get('element') == sites[j].get('element'):
                same += w
    if total <= 0.0:
        return 0.0
    return (same / total - expected) / (1.0 - expected)"},{"description":"Soft contacts between atoms with electronegativity at least 2.4 per occupied atom, counting each directed pair by half.","name":"electronegative_network_contact_density","source":"def feature(s):
