    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            if en[i] is not None and en[j] is not None and en[i] >= 2.4 and en[j] >= 2.4:
                u = d / (1.5 * (radii[i] + radii[j]))
                total += occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
    return total / (2.0 * max(sum(occ), 1e-12))"},{"description":"Occupancy-weighted coefficient of variation of each site's smallest radius-normalized contact distance.","name":"nearest_reduced_contact_heterogeneity","source":"def feature(s):
    if not s:
