        if 0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0:
            if nearest[i] > 0.0 and d <= 1.25 * nearest[i]:
                total += occ[i] * occ[j]
    return total / max(sum(occ), 1e-12)"},{"description":"Mean relative gap between the adaptive first-shell boundary and the next neighbor, right-censored at 6 angstroms.","name":"first_shell_isolation_gap","source":"def feature(s):
    if not s:
