    outer = [6.0 for x in sites]
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0 and occ[i] > 0.0 and occ[j] > 0.0:
            if nearest[i] == 0.0 or d < nearest[i]:
