@9 n="electronegative_homoelement_soft_coordination" d="Soft coordination from same-element contacts with electronegativity at least 2.5, averaged over all occupied sites." B=1036
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    en = [(props.get(a.get('element')) or {}).get('eneg') for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if sites[i].get('element') != sites[j].get('element'):
            continue
        if radii[i] <= 0 or radii[j] <= 0 or en[i] is None or en[i] < 2.5:
            continue
        total += occ[i] * occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
    return float(total / (0.1225 * amount))
@end
@10 n="contact_direction_isotropy" d="Normalized determinant of the soft-contact direction second moment: zero for planar directions and one for isotropic directions." B=2006
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    xx = 0.0
    yy = 0.0
    zz = 0.0
    xy = 0.0
    xz = 0.0
    yz = 0.0
    weight = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        w = occ[i] * occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        if w <= 0:
            continue
        fi = sites[i].get('frac_coords') or []
        fj = sites[j].get('frac_coords') or []
        image = edge.get('image') or [0, 0, 0]
        if len(fi) != 3 or len(fj) != 3 or len(image) != 3:
            continue
        a = fj[0] + image[0] - fi[0]
        b = fj[1] + image[1] - fi[1]
        c = fj[2] + image[2] - fi[2]
        x = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
        y = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
        z = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
        norm2 = x * x + y * y + z * z
        if norm2 <= 0:
            continue
        q = w / norm2
        xx += q * x * x
        yy += q * y * y
        zz += q * z * z
        xy += q * x * y
        xz += q * x * z
        yz += q * y * z
        weight += w
    if weight <= 0:
        return 0.0
    determinant = xx * yy * zz + 2.0 * xy * xz * yz - xx * yz * yz - yy * xz * xz - zz * xy * xy
    return float(min(1.0, max(0.0, 27.0 * determinant / weight ** 3)))
@end
@11 n="atomic_charge_relaxation_scale" d="Per-atom neutral quadratic charge-relaxation scale derived from isolated-atom ionization energies and electron affinities." B=920
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    quadratic = 0.0
    linear = 0.0
    compliance = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        p = props.get(el) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is None or affinity is None or ionization <= 0:
            continue
        hardness = ionization - affinity
        if hardness <= 0:
            continue
        chi = 0.5 * (ionization + affinity)
        quadratic += x * chi * chi / hardness
        linear += x * chi / hardness
        compliance += x / hardness
        amount += x
    if compliance <= 0 or amount <= 0:
        return 0.0
    return float(max(0.0, 0.5 * (quadratic - linear * linear / compliance) / amount))
@end
@12 n="local_contact_direction_imbalance" d="Occupancy-weighted mean squared resultant of local soft-contact unit directions; zero for inversion-balanced environments." B=2157
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    props = s.get('element_properties') or {}
    edges = s.get('neighbors') or []
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    total = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0 or radii[i] <= 0:
            continue
        fi = sites[i].get('frac_coords') or []
        if len(fi) != 3:
            continue
        sx = 0.0
        sy = 0.0
        sz = 0.0
        weight = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or radii[j] <= 0:
                continue
            w = occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
            if w <= 0:
                continue
            fj = sites[j].get('frac_coords') or []
            image = edge.get('image') or [0, 0, 0]
            if len(fj) != 3 or len(image) != 3:
                continue
            a = fj[0] + image[0] - fi[0]
            b = fj[1] + image[1] - fi[1]
            c = fj[2] + image[2] - fi[2]
            x = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
            y = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
            z = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
            norm2 = x * x + y * y + z * z
            if norm2 <= 0:
                continue
            q = w / norm2 ** 0.5
            sx += q * x
            sy += q * y
            sz += q * z
            weight += w
        if weight > 0:
            imbalance = (sx * sx + sy * sy + sz * sz) / (weight * weight)
            total += occ[i] * min(1.0, max(0.0, imbalance))
            amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0
@end
