        norm2 = x * x + y * y + z * z
        if norm2 <= 0:
            continue
        q = w / norm2
        xx += q * x * x
        yy += q * y * y
        zz += q * z * z
        xy += q * x * y
        xz += q * x * z
        yz += q * y * z
        weight += w
    if weight <= 0:
        return 0.0
    determinant = xx * yy * zz + 2.0 * xy * xz * yz - xx * yz * yz - yy * xz * xz - zz * xy * xy
    return float(min(1.0, max(0.0, 27.0 * determinant / weight ** 3)))"},{"description":"Per-atom neutral quadratic charge-relaxation scale derived from isolated-atom ionization energies and electron affinities.","name":"atomic_charge_relaxation_scale","source":"def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
