    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        p = props.get(el) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is None or affinity is None or ionization <= 0:
            continue
        hardness = ionization - affinity
        if hardness <= 0:
            continue
        chi = 0.5 * (ionization + affinity)
        quadratic += x * chi * chi / hardness
        linear += x * chi / hardness
        compliance += x / hardness
        amount += x
    if compliance <= 0 or amount <= 0:
        return 0.0
    return float(max(0.0, 0.5 * (quadratic - linear * linear / compliance) / amount))"},{"description":"Composition-averaged covalent-sphere volume divided by atomic volume, a dimensionless packing proxy.","name":"covalent_sphere_packing","source":"def feature(s):
