            second += occ[i] * best * best
    if weight <= 0.0 or first <= 0.0:
        return 0.0
    mean = first / weight
    return max(0.0, second / weight - mean * mean) ** 0.5 / mean
@end
@13 n="local_contact_direction_anisotropy" d="Mean rotationally invariant anisotropy of soft-contact direction tensors; zero is isotropic and one is collinear." B=2457
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    total_weight = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        position = sites[i].get('frac_coords') or []
        if len(position) != 3:
            continue
        xx = 0.0
        yy = 0.0
        zz = 0.0
        xy = 0.0
        xz = 0.0
        yz = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d < 6.0):
                continue
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[j] * max(0.0, 1.0 - u * u) ** 2
            if w <= 0.0:
                continue
            other = sites[j].get('frac_coords') or []
            image = b.get('image') or [0, 0, 0]
            if len(other) != 3 or len(image) != 3:
                continue
            a = other[0] + image[0] - position[0]
            bfrac = other[1] + image[1] - position[1]
            c = other[2] + image[2] - position[2]
            dx = a * matrix[0][0] + bfrac * matrix[1][0] + c * matrix[2][0]
            dy = a * matrix[0][1] + bfrac * matrix[1][1] + c * matrix[2][1]
            dz = a * matrix[0][2] + bfrac * matrix[1][2] + c * matrix[2][2]
            norm2 = dx * dx + dy * dy + dz * dz
            if norm2 <= 1e-12:
                continue
            scale = w / norm2
            xx += scale * dx * dx
            yy += scale * dy * dy
            zz += scale * dz * dz
            xy += scale * dx * dy
            xz += scale * dx * dz
            yz += scale * dy * dz
        trace = xx + yy + zz
        if trace > 1e-12:
            square_trace = xx * xx + yy * yy + zz * zz + 2.0 * (xy * xy + xz * xz + yz * yz)
            anisotropy = 1.5 * square_trace / (trace * trace) - 0.5
            total += occ[i] * min(1.0, max(0.0, anisotropy))
            total_weight += occ[i]
    return total / max(total_weight, 1e-12)
@end
@14 n="nominal_valence_electron_density" d="Composition-averaged H3 valence-electron count divided by atomic volume." B=820
def feature(s):
    if not s:
        return 0.0
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        sites = s.get('sites') or []
        count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites)
        cell = (s.get('lattice') or {}).get('volume_A3') or 0.0
        if cell <= 0.0 or count <= 0.0:
            return 0.0
        volume = cell / count
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        valence = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and fraction > 0.0 and valence is not None and valence >= 0.0:
            total += fraction * valence
            weight += fraction
    return total / (max(weight, 1e-12) * volume)
@end
