        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and 0.0 < d < 6.0:
            if ion[i] is not None and ion[j] is not None:
                w = occ[i] * occ[j] * (1.0 - d / 6.0) ** 2 / d
                cost = min(ion[i] - affinity[j], ion[j] - affinity[i])
                total += w * cost
                weight += w
    return total / max(weight, 1e-12)"},{"description":"Atomic volume in cubic angstroms, with a lattice-volume fallback.","name":"atomic_volume","source":"def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3') or 0.0
    if v > 0.0:
        return v
    sites = s.get('sites') or []
    count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites)
    volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
    if count > 0.0 and volume > 0.0:
        return volume / count
    return 0.0"},{"description":"Nominal covalent-sphere volume divided by atomic volume; overlapping spheres are permitted.","name":"covalent_sphere_packing","source":"def feature(s):
    if not s:
        return 0.0
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is not None and fraction > 0.0:
            radius = max(0.1, (props.get(element) or {}).get('covalent_radius_A') or 1.3)
            total += fraction * radius ** 3
            weight += fraction
    return 4.188790204786391 * total / (max(weight, 1e-12) * volume)"},{"description":"Fraction of near-covalent contacts that are homonuclear with electronegativity at least 2.4.","name":"electronegative_homonuclear_contact_fraction","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0:
            reduced = d / (radii[i] + radii[j])
            if reduced <= 1.3:
                w = occ[i] * occ[j]
                weight += w
                if sites[i].get('element') == sites[j].get('element') and en[i] is not None and en[i] >= 2.4:
                    total += w
    return total / max(weight, 1e-12)"},{"description":"Mean occupied coordination using a compact kernel vanishing at 1.5 times the covalent-radius sum.","name":"soft_covalent_coordination","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            u = d / (1.5 * (radii[i] + radii[j]))
            w = max(0.0, 1.0 - u * u) ** 2
            total += occ[i] * occ[j] * w
    return total / max(sum(occ), 1e-12)"},{"description":"Occupancy-weighted coefficient of variation of sitewise soft covalent coordination.","name":"soft_coordination_heterogeneity","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    first = 0.0
    second = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        coordination = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d < 6.0:
                u = d / (1.5 * (radii[i] + radii[j]))
                coordination += occ[j] * max(0.0, 1.0 - u * u) ** 2
        first += occ[i] * coordination
        second += occ[i] * coordination * coordination
    weight = sum(occ)
    if weight <= 0.0 or first <= 0.0:
        return 0.0
    mean = first / weight
    variance = max(0.0, second / weight - mean * mean)
    return variance ** 0.5 / mean"},{"description":"Soft-contact-weighted coefficient of variation of distances normalized by covalent-radius sums.","name":"reduced_contact_length_dispersion","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    weight = 0.0
    first = 0.0
    second = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            reduced = d / (radii[i] + radii[j])
            u = reduced / 1.5
            w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
            weight += w
            first += w * reduced
            second += w * reduced * reduced
    if weight <= 0.0 or first <= 0.0:
        return 0.0
    mean = first / weight
    return max(0.0, second / weight - mean * mean) ** 0.5 / mean"},{"description":"Excess homonuclear soft-contact fraction relative to composition-random mixing, normalized by available heteronuclear fraction.","name":"chemical_contact_assortativity","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    fractions = [f for f in (s.get('composition') or {}).values() if f is not None and f > 0.0]
    total_fraction = sum(fractions)
    if total_fraction <= 0.0:
        return 0.0
    expected = sum(f * f for f in fractions) / (total_fraction * total_fraction)
    if expected >= 1.0 - 1e-12:
        return 0.0
    total = 0.0
    same = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
            total += w
            if sites[i].get('element') == sites[j].get('element'):
                same += w
    if total <= 0.0:
        return 0.0
    return (same / total - expected) / (1.0 - expected)"},{"description":"Occupancy-weighted coefficient of variation of each site's smallest radius-normalized contact distance.","name":"nearest_reduced_contact_heterogeneity","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    first = 0.0
    second = 0.0
    weight = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        best = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and d > 0.0 and occ[j] > 0.0:
                reduced = d / (radii[i] + radii[j])
                if best == 0.0 or reduced < best:
                    best = reduced
        if best > 0.0:
            weight += occ[i]
            first += occ[i] * best
            second += occ[i] * best * best
    if weight <= 0.0 or first <= 0.0:
        return 0.0
    mean = first / weight
    return max(0.0, second / weight - mean * mean) ** 0.5 / mean"},{"description":"Mean rotationally invariant anisotropy of soft-contact direction tensors; zero is isotropic and one is collinear.","name":"local_contact_direction_anisotropy","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    total_weight = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        position = sites[i].get('frac_coords') or []
        if len(position) != 3:
            continue
        xx = 0.0
        yy = 0.0
        zz = 0.0
        xy = 0.0
        xz = 0.0
        yz = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d < 6.0):
                continue
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[j] * max(0.0, 1.0 - u * u) ** 2
            if w <= 0.0:
                continue
            other = sites[j].get('frac_coords') or []
            image = b.get('image') or [0, 0, 0]
            if len(other) != 3 or len(image) != 3:
                continue
            a = other[0] + image[0] - position[0]
            bfrac = other[1] + image[1] - position[1]
            c = other[2] + image[2] - position[2]
            dx = a * matrix[0][0] + bfrac * matrix[1][0] + c * matrix[2][0]
            dy = a * matrix[0][1] + bfrac * matrix[1][1] + c * matrix[2][1]
            dz = a * matrix[0][2] + bfrac * matrix[1][2] + c * matrix[2][2]
            norm2 = dx * dx + dy * dy + dz * dz
            if norm2 <= 1e-12:
                continue
            scale = w / norm2
            xx += scale * dx * dx
            yy += scale * dy * dy
            zz += scale * dz * dz
            xy += scale * dx * dy
            xz += scale * dx * dz
            yz += scale * dy * dz
        trace = xx + yy + zz
        if trace > 1e-12:
            square_trace = xx * xx + yy * yy + zz * zz + 2.0 * (xy * xy + xz * xz + yz * yz)
            anisotropy = 1.5 * square_trace / (trace * trace) - 0.5
            total += occ[i] * min(1.0, max(0.0, anisotropy))
            total_weight += occ[i]
    return total / max(total_weight, 1e-12)"},{"description":"Signed main-group octet-balance proxy per atom: groups 1, 2, 13 and 14 donate, groups 15–17 accept; other groups contribute zero.","name":"nominal_main_group_charge_imbalance","source":"def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0.0:
            continue
        group = (props.get(element) or {}).get('group')
        charge = 0.0
        if group == 1 or group == 2:
            charge = float(group)
        elif group == 13 or group == 14:
            charge = float(group - 10)
        elif group == 15 or group == 16 or group == 17:
            charge = float(group - 18)
        total += fraction * charge
        weight += fraction
    return total / max(weight, 1e-12)"},{"description":"Fraction of occupied atoms that are electronegative group-14–17 sites with at most two occupied neighbors inside 1.25 covalent-radius sums.","name":"low_coordination_electronegative_fraction","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for i in range(n):
        p = props.get(sites[i].get('element')) or {}
        en = p.get('eneg')
        group = p.get('group')
        if occ[i] <= 0.0 or en is None or en < 2.4 or group is None or not (14 <= group <= 17):
            continue
        coordination = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.25 * (radii[i] + radii[j]):
                coordination += occ[j]
        if coordination <= 2.0 + 1e-9:
            total += occ[i]
    return total / max(sum(occ), 1e-12)"},{"description":"Squared contraction below the covalent-radius sum for electronegative homonuclear contacts, summed per atom with directed-pair correction.","name":"electronegative_short_bond_density","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if sites[i].get('element') == sites[j].get('element') and en[i] is not None and en[i] >= 2.4:
            contraction = max(0.0, 1.0 - d / (radii[i] + radii[j]))
            total += occ[i] * occ[j] * contraction * contraction
    return total / (2.0 * max(sum(occ), 1e-12))"},{"description":"Mean occupied coordination within 1.25 times each site's nearest occupied-neighbor distance, independent of covalent radii.","name":"adaptive_first_shell_coordination","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        coordination = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.25 * nearest:
                coordination += occ[j]
        total += occ[i] * coordination
    return total / max(sum(occ), 1e-12)"},{"description":"Mean squared sitewise signed electronegativity contrast against the soft-contact neighborhood; distinguishes coherent local polarity from cancellation.","name":"local_squared_electronegativity_contrast","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0 or en[i] is None:
            continue
        contrast = 0.0
        weight = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and en[j] is not None and 0.0 < d < 6.0:
                u = d / (1.5 * (radii[i] + radii[j]))
                w = occ[j] * max(0.0, 1.0 - u * u) ** 2
                contrast += w * (en[j] - en[i])
                weight += w
        if weight > 1e-12:
            total += occ[i] * (contrast / weight) ** 2
            centers += occ[i]
    return total / max(centers, 1e-12)"},{"description":"Mean sitewise relative radial variance inside 1.5 nearest-neighbor distances, weighted by inverse sixth-power distance.","name":"local_first_shell_radial_distortion","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        weight = 0.0
        first = 0.0
        second = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.5 * nearest:
                ratio = d / nearest
                w = occ[j] / ratio ** 6
                weight += w
                first += w * ratio
                second += w * ratio * ratio
        if weight > 1e-12 and first > 0.0:
            mean = first / weight
            distortion = max(0.0, second / weight - mean * mean) / (mean * mean)
            total += occ[i] * distortion
            centers += occ[i]
    return total / max(centers, 1e-12)"},{"description":"Mean squared normalized vector sum of soft-contact directions; measures local directional imbalance independently of second-rank anisotropy.","name":"local_contact_vector_imbalance","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        position = sites[i].get('frac_coords') or []
        if len(position) != 3:
            continue
        vx = 0.0
        vy = 0.0
        vz = 0.0
        weight = 0.0
        for bond in bonds:
            if bond.get('i', -1) != i:
                continue
            j = bond.get('j', -1)
            d = bond.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d < 6.0):
                continue
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[j] * max(0.0, 1.0 - u * u) ** 2
            if w <= 0.0:
                continue
            other = sites[j].get('frac_coords') or []
            image = bond.get('image') or [0, 0, 0]
            if len(other) != 3 or len(image) != 3:
                continue
            a = other[0] + image[0] - position[0]
            b = other[1] + image[1] - position[1]
            c = other[2] + image[2] - position[2]
            dx = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
            dy = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
            dz = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
            norm2 = dx * dx + dy * dy + dz * dz
            if norm2 <= 1e-12:
                continue
            scale = w / norm2 ** 0.5
            vx += scale * dx
            vy += scale * dy
            vz += scale * dz
            weight += w
        if weight > 1e-12:
            imbalance = (vx * vx + vy * vy + vz * vz) / (weight * weight)
            total += occ[i] * min(1.0, max(0.0, imbalance))
            centers += occ[i]
    return total / max(centers, 1e-12)"},{"description":"Mean normalized contrast between nearest heteronuclear and homonuclear reduced distances around electronegative sites; unavailable contact types use a reduced-distance cap of three.","name":"electronegative_contact_separation","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0 or en[i] is None or en[i] < 2.4:
            continue
        same = 3.0
        different = 3.0
        found = False
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if not (0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0):
                continue
