                    p4 = (35.0 * c2 * c2 - 30.0 * c2 + 3.0) / 8.0
                    pair_weights = weights.reshape(-1, 1) * weights.reshape(1, -1)
                    q4 = float(np.sum(pair_weights * p4)) / (weight * weight)
                    result += occ[i] * max(0.0, min(1.0, q4))
                    total += occ[i]
    if total <= 0:
        return 0.0
    return result / total
@end
@14 n="electronegative_p_block_network_burden" d="Short-contact burden per occupied atom between electronegative group-15–17 atoms, sensitive to polyanion and molecular motifs." B=1223
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    groups = [(props.get(t.get('element')) or {}).get('group') for t in sites]
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    selected = [groups[i] is not None and 15 <= groups[i] <= 17 and en[i] is not None and en[i] >= 2.5 for i in range(n)]
    result = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and selected[i] and selected[j] and occ[i] > 0 and occ[j] > 0 and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                x6 = x2 * x2 * x2
                result += occ[i] * occ[j] / (1.0 + x6 * x6)
    return 0.5 * result / atoms
@end
@15 n="contact_charge_transfer_softness" d="Contact-weighted squared Mulliken-electronegativity difference divided by summed atomic hardness, per occupied atom." B=1450
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    ion = [(props.get(t.get('element')) or {}).get('first_ionization_energy_eV') for t in sites]
    affinity = [(props.get(t.get('element')) or {}).get('electron_affinity_eV') for t in sites]
    result = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and ion[i] is not None and ion[j] is not None and affinity[i] is not None and affinity[j] is not None:
                hi = ion[i] - affinity[i]
                hj = ion[j] - affinity[j]
                if hi > 0 and hj > 0:
                    delta = 0.5 * (ion[i] + affinity[i] - ion[j] - affinity[j])
                    x = d / (a + b)
                    x2 = x * x
                    w = occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
                    result += w * delta * delta / (hi + hj)
    return 0.5 * result / atoms
@end
@16 n="maximum_site_nearest_contact_stretch" d="Largest site minimum distance divided by the covalent-radius sum; measures the most weakly contacted occupied site." B=1059
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    result = 0.0
    for i in range(n):
        a = radii[i]
        if occ[i] > 0 and a is not None and a > 0:
            nearest = 0.0
            for edge in edges:
                if edge.get('i', -1) == i:
                    j = edge.get('j', -1)
                    d = edge.get('distance_A')
                    if 0 <= j < n and occ[j] > 0 and d is not None and d > 0:
                        b = radii[j]
                        if b is not None and b > 0:
                            stretch = d / (a + b)
                            if nearest <= 0 or stretch < nearest:
                                nearest = stretch
            if nearest > result:
                result = nearest
    return result
@end
@17 n="volume_per_occupied_atom" d="Unit-cell volume per occupancy-summed atom in cubic angstroms, with supplied volume-per-atom fallback." B=418
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    atoms = sum(max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites)
    volume = (s.get('lattice') or {}).get('volume_A3')
    if atoms > 0 and volume is not None and volume > 0:
        return volume / atoms
    value = s.get('volume_per_atom_A3')
    if value is not None and value > 0:
        return float(value)
    return 0.0
@end
@18 n="local_first_shell_direction_anisotropy" d="Mean local first-shell second-moment anisotropy, retaining directional asymmetry that cancels in the global tensor." B=2595
def feature(s):
    if not s:
        return 0.0
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    total = 0.0
    result = 0.0
    for i in range(n):
        fi = sites[i].get('frac_coords')
        if occ[i] > 0 and fi is not None:
            nearby = [edge for edge in edges if edge.get('i', -1) == i and 0 <= edge.get('j', -1) < n and occ[edge.get('j', -1)] > 0 and edge.get('distance_A') is not None and edge.get('distance_A') > 0]
            if nearby:
                cutoff = 1.25 * min(edge.get('distance_A') for edge in nearby)
                weight = 0.0
                xx = 0.0
                yy = 0.0
                zz = 0.0
                xy = 0.0
                xz = 0.0
                yz = 0.0
                for edge in nearby:
                    if edge.get('distance_A') <= cutoff:
                        j = edge.get('j')
                        fj = sites[j].get('frac_coords')
                        image = edge.get('image')
                        if fj is not None and image is not None:
                            u = fj[0] + image[0] - fi[0]
                            v = fj[1] + image[1] - fi[1]
                            t = fj[2] + image[2] - fi[2]
                            dx = u * matrix[0][0] + v * matrix[1][0] + t * matrix[2][0]
                            dy = u * matrix[0][1] + v * matrix[1][1] + t * matrix[2][1]
                            dz = u * matrix[0][2] + v * matrix[1][2] + t * matrix[2][2]
                            norm2 = dx * dx + dy * dy + dz * dz
                            if norm2 > 0:
                                scale = occ[j] / norm2
                                weight += occ[j]
                                xx += scale * dx * dx
                                yy += scale * dy * dy
                                zz += scale * dz * dz
                                xy += scale * dx * dy
                                xz += scale * dx * dz
                                yz += scale * dy * dz
                if weight > 0:
                    invariant = (xx * xx + yy * yy + zz * zz + 2.0 * (xy * xy + xz * xz + yz * yz)) / (weight * weight)
                    anisotropy = max(0.0, min(1.0, 1.5 * invariant - 0.5))
                    result += occ[i] * anisotropy
                    total += occ[i]
    if total <= 0:
        return 0.0
    return result / total
@end
