def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    total = 0.0
    sphere = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        total += o
        r = (props.get(t.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            sphere += o * r * r * r
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * total
    if volume <= 0:
        return 0.0
    return 4.1887902047863905 * sphere / volume

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    electrons = 0.0
    total = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        total += o
        v = (props.get(t.get('element')) or {}).get('valence_electrons')
        if v is not None:
            electrons += o * v
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * total
    if volume <= 0:
        return 0.0
    return electrons / volume

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if occ[i] > 0 and occ[j] > 0 and a is not None and b is not None and a > 0 and b > 0:
                overlap = max(0.0, 1.0 - d / (a + b))
                total += occ[i] * occ[j] * overlap * overlap
    return 0.5 * total / atoms

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    total = 0.0
    first = 0.0
    for i in range(n):
        if occ[i] > 0:
            pairs = [(edge.get('distance_A'), occ[edge.get('j', -1)]) for edge in edges if edge.get('i', -1) == i and 0 <= edge.get('j', -1) < n and occ[edge.get('j', -1)] > 0 and edge.get('distance_A') is not None and edge.get('distance_A') > 0]
            if pairs:
                cutoff = 1.25 * min(d for d, o in pairs)
                coordination = sum(o for d, o in pairs if d <= cutoff)
                total += occ[i]
                first += occ[i] * coordination
    if total <= 0:
        return 0.0
    return first / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    counts = {}
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    for i in range(n):
        element = sites[i].get('element')
        counts[element] = counts.get(element, 0.0) + occ[i]
    random_unlike = 1.0 - sum((v / atoms) ** 2 for v in counts.values())
    total = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                w = occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
                total += w
                if sites[i].get('element') != sites[j].get('element'):
                    unlike += w
    if total <= 0:
        return 0.0
    return unlike / total - random_unlike

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [0.0 for i in range(n)]
    outer = [6.0 for i in range(n)]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and d > 0:
            if nearest[i] <= 0 or d < nearest[i]:
                nearest[i] = d
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and nearest[i] > 0:
            if d > 1.25 * nearest[i] and d < outer[i]:
                outer[i] = d
    total = 0.0
    result = 0.0
    for i in range(n):
        if occ[i] > 0 and nearest[i] > 0:
            result += occ[i] * float(np.log(max(1.0, outer[i] / nearest[i])))
            total += occ[i]
    if total <= 0:
        return 0.0
    return result / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    nearest = [0.0 for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                if nearest[i] <= 0 or x < nearest[i]:
                    nearest[i] = x
    total = sum(occ[i] for i in range(n) if nearest[i] > 0)
    if total <= 0:
        return 0.0
    return sum(occ[i] * nearest[i] for i in range(n) if nearest[i] > 0) / total

