    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0 or en[i] is None:
            continue
        contrast = 0.0
        weight = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and en[j] is not None and 0.0 < d < 6.0:
                u = d / (1.5 * (radii[i] + radii[j]))
                w = occ[j] * max(0.0, 1.0 - u * u) ** 2
                contrast += w * (en[j] - en[i])
                weight += w
        if weight > 1e-12:
            total += occ[i] * (contrast / weight) ** 2
            centers += occ[i]
    return total / max(centers, 1e-12)
