    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    total = 0.0
    amount = 0.0
    for i in range(n):
        fi = sites[i].get('frac_coords') or []
        if occ[i] <= 0 or radii[i] <= 0 or len(fi) != 3:
            continue
        xx = 0.0
        yy = 0.0
        zz = 0.0
        xy = 0.0
        xz = 0.0
        yz = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or radii[j] <= 0:
                continue
            w = occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
            if w <= 0:
                continue
            fj = sites[j].get('frac_coords') or []
            image = edge.get('image') or [0, 0, 0]
            if len(fj) != 3 or len(image) != 3:
                continue
            a = fj[0] + image[0] - fi[0]
            b = fj[1] + image[1] - fi[1]
            c = fj[2] + image[2] - fi[2]
            x = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
            y = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
            z = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
            norm2 = x * x + y * y + z * z
            if norm2 <= 0:
                continue
            q = w / norm2
            xx += q * x * x
            yy += q * y * y
            zz += q * z * z
            xy += q * x * y
            xz += q * x * z
            yz += q * y * z
        trace = xx + yy + zz
        square_trace = xx * xx + yy * yy + zz * zz + 2.0 * (xy * xy + xz * xz + yz * yz)
        if trace <= 0 or square_trace <= 0:
            continue
        dimension = min(3.0, max(1.0, trace * trace / square_trace))
        total += occ[i] * dimension
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0
@end
@13 n="valence_electron_density" d="Composition-averaged H3 valence-electron count divided by atomic volume, in electrons per cubic angstrom." B=668
def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        valence = (props.get(el) or {}).get('valence_electrons')
        if valence is None or valence < 0:
            continue
        total += x * valence
        amount += x
    return float(total / (amount * v)) if amount > 0 else 0.0
@end
