            continue
        if sites[i].get('element') != sites[j].get('element'):
            continue
        rs = radii[i] + radii[j]
        if d <= 1.25 * rs:
            order = min(3.0, 2.718281828459045 ** max(-5.0, min(1.1, (rs - d) / 0.3)))
            total += occ[i] * occ[j] * order
    return total / max(sum(occ), 1e-12)"},{"description":"Within-pnictogen variance of local octet residuals, using capped exponential homonuclear bond-order estimates; zero without pnictogens.","name":"pnictogen_local_octet_residual_variance","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    groups = [(props.get(x.get('element')) or {}).get('group') for x in sites]
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    residual = [-3.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if groups[i] != 15 or sites[i].get('element') != sites[j].get('element'):
            continue
        rs = radii[i] + radii[j]
        if d <= 1.25 * rs:
            order = min(3.0, 2.718281828459045 ** max(-5.0, min(1.1, (rs - d) / 0.3)))
            residual[i] += occ[j] * order
    weight = sum(occ[i] for i in range(n) if groups[i] == 15)
    if weight <= 0.0:
        return 0.0
    mean = sum(occ[i] * residual[i] for i in range(n) if groups[i] == 15) / weight
    return sum(occ[i] * (residual[i] - mean) ** 2 for i in range(n) if groups[i] == 15) / weight"},{"description":"Soft heteronuclear-contact mean of the lower free-atom electron-transfer cost minus the unit-charge Coulomb attraction, in eV.","name":"heteronuclear_atomic_transfer_cost","source":"def feature(s):
