        if count > 0.0 and cell_volume > 0.0:
            volume = cell_volume / count
    if volume <= 0.0 or weight <= 0.0:
        return 0.0
    return total / (weight * volume)"}],"notes":"Distance-derived bond orders and octet residuals are proxies, not oxidation states; atomic transfer costs omit screening, neighborhoods end at 6 Å, and missing covalent radii use 1.3 Å.","queries":[{"include_all":["N"],"n":29},{"exclude":["O","F","N"],"include_all":["P"],"n":21},{"include_all":["O"],"include_any":["Mn","Re","Cu","Tl","Sc"],"n":25,"n_elements":[3,5]}],"rationale":"Retain contact and directional descriptors; replace weak motif scores with homonuclear valence compensation, local charge variance, transfer cost, and electron density. Sample remaining N, P, and ox N"}

