            vz += scale * dz
            weight += w
        if weight > 1e-12:
            imbalance = (vx * vx + vy * vy + vz * vz) / (weight * weight)
            total += occ[i] * min(1.0, max(0.0, imbalance))
            centers += occ[i]
    return total / max(centers, 1e-12)"},{"description":"Mean relative gap between the outermost adaptive first-shell contact and the next contact; ratios capped at three, unresolved gaps omitted.","name":"adaptive_first_shell_gap","source":"def feature(s):
