                elif outer == 0.0 or d < outer:
                    outer = d
        if outer > 0.0:
            total += occ[i] * (min(3.0, outer / inner) - 1.0)
            weight += occ[i]
    return total / max(weight, 1e-12)"},{"description":"Soft heteronuclear-contact mean of the lower free-atom electron-transfer cost minus the unit-charge Coulomb attraction, in eV.","name":"heteronuclear_atomic_transfer_cost","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    affinity = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d < 6.0):
            continue
        if sites[i].get('element') == sites[j].get('element'):
            continue
        if ion[i] is None or ion[j] is None or affinity[i] is None or affinity[j] is None:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
        cost = min(ion[i] - affinity[j], ion[j] - affinity[i]) - 14.399645478 / max(d, 0.1)
        total += w * cost
        weight += w
    return total / max(weight, 1e-12)"},{"description":"Composition-averaged H3 valence-electron count divided by atomic volume, in electrons per cubic angstrom; unavailable elements are omitted.","name":"nominal_valence_electron_density","source":"def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0.0:
            continue
        value = (props.get(element) or {}).get('valence_electrons')
        if value is not None and value >= 0.0:
            total += fraction * value
            weight += fraction
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in s.get('sites') or [])
        cell_volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
        if count > 0.0 and cell_volume > 0.0:
            volume = cell_volume / count
    if volume <= 0.0 or weight <= 0.0:
        return 0.0
    return total / (weight * volume)"},{"description":"Excess homonuclear bond-order proxy per occupied atom for groups 14–16; distance-derived orders are capped at three and directed pairs are halved.","name":"homonuclear_multiple_bond_density","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
