            continue
        reduced = d / (ri + rj)
        if reduced < 1.0:
            order = min(3.0, 2.0 ** min(2.0, (1.0 - reduced) / 0.12))
            total += 0.5 * occ[i] * occ[j] * (order - 1.0)
    return total / max(sum(occ), 1e-12)"},{"description":"Signed main-group octet balance per occupied atom, corrected by homonuclear group-15–17 bond orders with a smooth cutoff at 1.3 radius sums.","name":"homonuclear_bond_compensated_octet_balance","source":"def feature(s):
