def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    elements = [t.get('element') for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    same = sum(occ[i] * occ[j] for i in range(n) for j in range(n) if elements[i] == elements[j]) / (atoms * atoms)
    total = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                w = occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
                total += w
                if elements[i] != elements[j]:
                    unlike += w
    if total <= 0:
        return 0.0
    return unlike / total - (1.0 - same)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    weight = 0.0
    first = 0.0
    atoms = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        p = props.get(t.get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if o > 0 and ion is not None and affinity is not None and ion - affinity > 1e-8:
            hardness = ion - affinity
            chi = 0.5 * (ion + affinity)
            w = o / hardness
            weight += w
            first += w * chi
            atoms += o
    if weight <= 0 or atoms <= 0:
        return 0.0
    mean = first / weight
    result = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        p = props.get(t.get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if o > 0 and ion is not None and affinity is not None and ion - affinity > 1e-8:
            delta = 0.5 * (ion + affinity) - mean
            result += o * delta * delta / (ion - affinity)
    return result / atoms

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    nearest = {}
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                ratio = d / (a + b)
                old = nearest.get(i)
                if old is None or ratio < old:
                    nearest[i] = ratio
    total = sum(occ[i] for i in nearest)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * value for i, value in nearest.items()) / total
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (value - mean) ** 2 for i, value in nearest.items()) / total
    return float(np.sqrt(max(0.0, variance))) / mean

