@12 n="local_contact_direction_imbalance" d="Mean squared normalized resultant of local soft-contact unit directions, measuring directional imbalance." B=2152
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
