@15 n="hardness_scaled_chemical_potential_dispersion" d="Occupied mean squared deviations of neutral atomic electronegativity (IE+EA)/2, scaled by hardness IE-EA, about the inverse-hardness-weighted mean; eV." B=1205
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    weight = 0.0
    first = 0.0
    atoms = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        p = props.get(t.get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if o > 0 and ion is not None and affinity is not None and ion - affinity > 1e-8:
            hardness = ion - affinity
            chi = 0.5 * (ion + affinity)
            w = o / hardness
            weight += w
            first += w * chi
            atoms += o
    if weight <= 0 or atoms <= 0:
        return 0.0
    mean = first / weight
    result = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        p = props.get(t.get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if o > 0 and ion is not None and affinity is not None and ion - affinity > 1e-8:
            delta = 0.5 * (ion + affinity) - mean
            result += o * delta * delta / (ion - affinity)
    return result / atoms
