    total = 0.0
    result = 0.0
    for i in range(n):
        a = radii[i]
        if occ[i] > 0 and a is not None and a > 0:
            ratios = [edge.get('distance_A') / (a + radii[edge.get('j', -1)]) for edge in edges if edge.get('i', -1) == i and 0 <= edge.get('j', -1) < n and occ[edge.get('j', -1)] > 0 and radii[edge.get('j', -1)] is not None and radii[edge.get('j', -1)] > 0 and edge.get('distance_A') is not None and edge.get('distance_A') > 0]
            if ratios:
                result += occ[i] * min(ratios)
                total += occ[i]
    if total <= 0:
        return 0.0
    return result / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    elements = [t.get('element') for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    same = sum(occ[i] * occ[j] for i in range(n) for j in range(n) if elements[i] == elements[j]) / (atoms * atoms)
    total = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                w = occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
                total += w
                if elements[i] != elements[j]:
                    unlike += w
    if total <= 0:
        return 0.0
    return unlike / total - (1.0 - same)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    coordination = [0.0 for i in range(n)]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                coordination[i] += occ[j] / (1.0 + x2 * x2 * x2)
    total = sum(occ[i] for i in range(n) if radii[i] is not None and radii[i] > 0)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * coordination[i] for i in range(n) if radii[i] is not None and radii[i] > 0) / total
    if mean <= 1e-12:
        return 0.0
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n) if radii[i] is not None and radii[i] > 0) / total
    return variance / (mean * mean)

