    total = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        coordination = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.25 * nearest:
                coordination += occ[j]
        total += occ[i] * coordination
    return total / max(sum(occ), 1e-12)"},{"description":"Mean sitewise relative radial variance within 1.5 nearest-neighbor distances, using inverse-sixth-power weights.","name":"local_first_shell_radial_distortion","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        weight = 0.0
        first = 0.0
        second = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.5 * nearest:
                ratio = d / nearest
                w = occ[j] / ratio ** 6
                weight += w
                first += w * ratio
                second += w * ratio * ratio
        if weight > 1e-12 and first > 0.0:
            mean = first / weight
            distortion = max(0.0, second / weight - mean * mean) / (mean * mean)
            total += occ[i] * distortion
            centers += occ[i]
    return total / max(centers, 1e-12)"},{"description":"Mean squared normalized vector sum of soft-contact directions, measuring local directional imbalance.","name":"local_contact_vector_imbalance","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        position = sites[i].get('frac_coords') or []
        if len(position) != 3:
            continue
        vx = 0.0
        vy = 0.0
        vz = 0.0
        weight = 0.0
        for bond in bonds:
            if bond.get('i', -1) != i:
                continue
            j = bond.get('j', -1)
            d = bond.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d < 6.0):
                continue
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[j] * max(0.0, 1.0 - u * u) ** 2
            if w <= 0.0:
                continue
            other = sites[j].get('frac_coords') or []
            image = bond.get('image') or [0, 0, 0]
            if len(other) != 3 or len(image) != 3:
                continue
            a = other[0] + image[0] - position[0]
            b = other[1] + image[1] - position[1]
            c = other[2] + image[2] - position[2]
            dx = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
            dy = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
            dz = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
            norm2 = dx * dx + dy * dy + dz * dz
            if norm2 <= 1e-12:
                continue
            scale = w / norm2 ** 0.5
            vx += scale * dx
            vy += scale * dy
            vz += scale * dz
            weight += w
        if weight > 1e-12:
            imbalance = (vx * vx + vy * vy + vz * vz) / (weight * weight)
            total += occ[i] * min(1.0, max(0.0, imbalance))
            centers += occ[i]
    return total / max(centers, 1e-12)"},{"description":"Mean relative gap between the outermost adaptive first-shell contact and the next contact; ratios capped at three, unresolved gaps omitted.","name":"adaptive_first_shell_gap","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        inner = nearest
        outer = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if d <= 1.25 * nearest:
                    inner = max(inner, d)
                elif outer == 0.0 or d < outer:
                    outer = d
        if outer > 0.0:
            total += occ[i] * (min(3.0, outer / inner) - 1.0)
            weight += occ[i]
    return total / max(weight, 1e-12)"},{"description":"Soft heteronuclear-contact mean of the lower free-atom electron-transfer cost minus the unit-charge Coulomb attraction, in eV.","name":"heteronuclear_atomic_transfer_cost","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    affinity = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d < 6.0):
            continue
        if sites[i].get('element') == sites[j].get('element'):
            continue
        if ion[i] is None or ion[j] is None or affinity[i] is None or affinity[j] is None:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
        cost = min(ion[i] - affinity[j], ion[j] - affinity[i]) - 14.399645478 / max(d, 0.1)
        total += w * cost
        weight += w
    return total / max(weight, 1e-12)"},{"description":"Signed group-based donor–acceptor balance per occupied atom after homonuclear bond-order compensation on group-13–17 sites; group-3 sites contribute three donor units.","name":"homonuclear_corrected_octet_balance","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    total = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        element = sites[i].get('element')
