        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and occ[i] > 0 and occ[j] > 0:
            if d > 1.25 * nearest[i]:
                outside[i] = min(outside[i], d)
    result = 0.0
    weight = 0.0
    for i in range(n):
        if occ[i] > 0 and nearest[i] <= 6.0:
            cutoff = 1.25 * nearest[i]
            result += occ[i] * float(np.log(max(1.0, outside[i] / cutoff)))
