def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    atoms = 0.0
    known = 0.0
    electrons = 0.0
    for site in sites:
        o = max(0.0, site.get('occupancy', 1.0) or 0.0)
        atoms += o
        v = (props.get(site.get('element')) or {}).get('valence_electrons')
        if v is not None and v >= 0:
            known += o
            electrons += o * v
    if atoms <= 0 or known <= 0:
        return 0.0
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        per_atom = s.get('volume_per_atom_A3')
        if per_atom is None or per_atom <= 0:
            return 0.0
        volume = per_atom * atoms
    return electrons * atoms / (known * volume)

