            weight += occ[i]
    return total / max(weight, 1e-12)"},{"description":"Soft heteronuclear-contact mean of the lower free-atom electron-transfer cost minus the unit-charge Coulomb attraction, in eV.","name":"heteronuclear_atomic_transfer_cost","source":"def feature(s):
