@13 n="valence_electron_number_density" d="Composition-averaged H3-convention valence electron count divided by atomic volume." B=677
def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        electrons = (props.get(el) or {}).get('valence_electrons')
        if electrons is None or electrons < 0:
            continue
        total += x * electrons
        amount += x
    return float(total / (amount * v)) if amount > 0 else 0.0

