        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            if en[i] is not None and en[j] is not None:
                u = d / (1.5 * (radii[i] + radii[j]))
                w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
                contrast = (en[i] - en[j]) ** 2
                total += w * contrast / (1.0 + contrast)
                weight += w
    return total / max(weight, 1e-12)"},{"description":"Soft-contact sum of bounded electronegativity contrast divided by distance, per occupied atom; directed pairs are halved.","name":"heteropolar_contact_strength_per_atom","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d < 6.0):
            continue
        if en[i] is None or en[j] is None:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
        contrast = (en[i] - en[j]) ** 2
        total += w * contrast / ((1.0 + contrast) * max(d, 0.1))
    return 0.5 * total / max(sum(occ), 1e-12)"},{"description":"Fraction of near-covalent contacts that are homonuclear with electronegativity at least 2.4.","name":"electronegative_homonuclear_contact_fraction","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
