    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        coordination = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.25 * nearest:
                coordination += occ[j]
        total += occ[i] * coordination
    return total / max(sum(occ), 1e-12)
@end
@12 n="local_first_shell_radial_distortion" d="Mean sitewise relative radial variance within 1.5 nearest-neighbor distances, using inverse-sixth-power weights." B=1424
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        weight = 0.0
        first = 0.0
        second = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.5 * nearest:
                ratio = d / nearest
                w = occ[j] / ratio ** 6
                weight += w
                first += w * ratio
                second += w * ratio * ratio
        if weight > 1e-12 and first > 0.0:
            mean = first / weight
            distortion = max(0.0, second / weight - mean * mean) / (mean * mean)
            total += occ[i] * distortion
            centers += occ[i]
    return total / max(centers, 1e-12)
@end
@13 n="local_contact_vector_imbalance" d="Mean squared normalized vector sum of soft-contact directions, measuring local directional imbalance." B=2209
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    matrix = (s.get('lattice') or {}).get('matrix') or []
    if len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        position = sites[i].get('frac_coords') or []
        if len(position) != 3:
            continue
        vx = 0.0
        vy = 0.0
        vz = 0.0
        weight = 0.0
        for bond in bonds:
            if bond.get('i', -1) != i:
                continue
            j = bond.get('j', -1)
            d = bond.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d < 6.0):
                continue
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[j] * max(0.0, 1.0 - u * u) ** 2
            if w <= 0.0:
                continue
            other = sites[j].get('frac_coords') or []
            image = bond.get('image') or [0, 0, 0]
            if len(other) != 3 or len(image) != 3:
                continue
            a = other[0] + image[0] - position[0]
            b = other[1] + image[1] - position[1]
            c = other[2] + image[2] - position[2]
            dx = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
            dy = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
            dz = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
            norm2 = dx * dx + dy * dy + dz * dz
            if norm2 <= 1e-12:
                continue
            scale = w / norm2 ** 0.5
            vx += scale * dx
            vy += scale * dy
            vz += scale * dz
            weight += w
        if weight > 1e-12:
            imbalance = (vx * vx + vy * vy + vz * vz) / (weight * weight)
            total += occ[i] * min(1.0, max(0.0, imbalance))
            centers += occ[i]
    return total / max(centers, 1e-12)
@end
@14 n="heteronuclear_atomic_transfer_cost" d="Soft heteronuclear-contact mean of the lower free-atom electron-transfer cost minus the unit-charge Coulomb attraction, in eV." B=1237
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    affinity = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d < 6.0):
            continue
        if sites[i].get('element') == sites[j].get('element'):
            continue
        if ion[i] is None or ion[j] is None or affinity[i] is None or affinity[j] is None:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
        cost = min(ion[i] - affinity[j], ion[j] - affinity[i]) - 14.399645478 / max(d, 0.1)
        total += w * cost
        weight += w
    return total / max(weight, 1e-12)
@end
@15 n="homonuclear_short_bond_excess" d="Excess short homonuclear bond-order proxy per occupied atom for electronegative group-14–17 sites; directed contacts are halved." B=1090
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if occ[i] * occ[j] <= 0.0 or sites[i].get('element') != sites[j].get('element'):
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or en is None or not (14 <= group <= 17) or en < 2.0:
            continue
        ratio = (radii[i] + radii[j]) / d
        if ratio > 1.0:
            order = min(3.0, min(2.0, ratio) ** 6)
            total += occ[i] * occ[j] * (order - 1.0)
    return 0.5 * total / max(sum(occ), 1e-12)
@end
@16 n="covalent_corrected_electron_balance" d="Signed main-group electron surplus per atom after radius-derived covalent bonds reduce the octet demand of electronegative group-14–17 sites." B=1863
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or en is None:
            continue
        if en < 2.0:
            if group == 1 or group == 2:
                total += occ[i] * group
            elif group == 13 or group == 14:
                total += occ[i] * (group - 10)
            continue
        if not (14 <= group <= 17):
            continue
        bond_sum = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d <= 6.0) or occ[j] <= 0.0:
                continue
            q = props.get(sites[j].get('element')) or {}
            other_group = q.get('group')
            other_en = q.get('eneg')
            if other_group is None or other_en is None or other_en < 2.0:
                continue
            main_group = 14 <= other_group <= 17
            hydrogen = other_group == 1 and q.get('row') == 1
            if not (main_group or hydrogen):
                continue
            radius_sum = radii[i] + radii[j]
            if d <= 1.3 * radius_sum:
                ratio = min(2.0, radius_sum / d)
                bond_sum += occ[j] * min(3.0, ratio ** 6)
        total += occ[i] * (bond_sum - (18.0 - group))
    return total / max(sum(occ), 1e-12)
@end
