{"features":[{"description":"Smallest occupied-contact distance divided by the covalent-radius sum.","name":"minimum_reduced_contact","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    best = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d > 0.0 and occ[i] * occ[j] > 0.0:
            value = d / (radii[i] + radii[j])
            if best == 0.0 or value < best:
                best = value
    return best"},{"description":"Soft-contact-weighted mean bounded squared electronegativity contrast, independent of contact count.","name":"soft_contact_ionicity","source":"def feature(s):
