        if not (0 <= i < n and 0 <= j < n and 0.0 < d < 6.0):
            continue
        if en[i] is None or en[j] is None:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
        contrast = (en[i] - en[j]) ** 2
        total += w * contrast / ((1.0 + contrast) * max(d, 0.1))
    return 0.5 * total / max(sum(occ), 1e-12)"},{"description":"Fraction of near-covalent contacts that are homonuclear with electronegativity at least 2.4.","name":"electronegative_homonuclear_contact_fraction","source":"def feature(s):
