            total += occ[i] * occ[j] * w
    return total / max(sum(occ), 1e-12)"},{"description":"Occupancy-weighted coefficient of variation of sitewise soft covalent coordination.","name":"soft_coordination_heterogeneity","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    first = 0.0
    second = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        coordination = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d < 6.0:
                u = d / (1.5 * (radii[i] + radii[j]))
                coordination += occ[j] * max(0.0, 1.0 - u * u) ** 2
        first += occ[i] * coordination
        second += occ[i] * coordination * coordination
    weight = sum(occ)
    if weight <= 0.0 or first <= 0.0:
        return 0.0
    mean = first / weight
    variance = max(0.0, second / weight - mean * mean)
    return variance ** 0.5 / mean"},{"description":"Soft-contact-weighted coefficient of variation of radius-normalized distances.","name":"reduced_contact_length_dispersion","source":"def feature(s):
    if not s:
