@10 n="local_first_shell_radial_distortion" d="Mean sitewise relative radial variance within 1.5 nearest-neighbor distances, using inverse-sixth-power weights." B=1424
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    centers = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        weight = 0.0
        first = 0.0
        second = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and 0.0 < d <= 6.0 and d <= 1.5 * nearest:
                ratio = d / nearest
                w = occ[j] / ratio ** 6
                weight += w
                first += w * ratio
                second += w * ratio * ratio
        if weight > 1e-12 and first > 0.0:
            mean = first / weight
            distortion = max(0.0, second / weight - mean * mean) / (mean * mean)
            total += occ[i] * distortion
            centers += occ[i]
    return total / max(centers, 1e-12)
