                contrast = (en[i] - en[j]) ** 2
                total += w * contrast / (1.0 + contrast)
                weight += w
    return total / max(weight, 1e-12)"},{"description":"Fraction of near-covalent contacts that are homonuclear with electronegativity at least 2.4.","name":"electronegative_homonuclear_contact_fraction","source":"def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0:
            reduced = d / (radii[i] + radii[j])
            if reduced <= 1.3:
                w = occ[i] * occ[j]
                weight += w
                if sites[i].get('element') == sites[j].get('element') and en[i] is not None and en[i] >= 2.4:
                    total += w
    return total / max(weight, 1e-12)"},{"description":"Mean occupied coordination with a compact kernel vanishing at 1.5 covalent-radius sums.","name":"soft_covalent_coordination","source":"def feature(s):
    if not s:
        return 0.0
