def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    edges = [(e.get('i'), e.get('j'), e.get('distance_A') or 0.0) for e in s.get('neighbors') or []]
    bonds = [(i, j, d) for i, j, d in edges if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d > 0 and radii[i] > 0 and radii[j] > 0 and d < 1.35 * (radii[i] + radii[j])]
    total = 0.0
    amount = 0.0
    for i, a in enumerate(sites):
        if radii[i] <= 0 or occ[i] <= 0:
            continue
        p = props.get(a.get('element')) or {}
        group = p.get('group')
        if p.get('Z') == 1:
            reference = 1.0
        elif group is not None and 13 <= group <= 17:
            reference = float(min(group - 10, 18 - group))
        else:
            continue
        coordination = sum(occ[j] * ((1.35 - d / (radii[i] + radii[j])) / 0.35) ** 2 for ii, j, d in bonds if ii == i)
        deficit = max(0.0, 1.0 - coordination / reference)
        total += occ[i] * deficit * deficit
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        electrons = (props.get(el) or {}).get('valence_electrons')
        if electrons is None or electrons < 0:
            continue
        total += x * electrons
        amount += x
    return float(total / (amount * v)) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    p = [props.get(a.get('element')) or {} for a in sites]
    radii = [a.get('covalent_radius_A') or 0.0 for a in p]
    ion = [a.get('first_ionization_energy_eV') for a in p]
    affinity = [a.get('electron_affinity_eV') for a in p]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ[i] for i in range(n) if radii[i] > 0 and ion[i] is not None and affinity[i] is not None and ion[i] > affinity[i])
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        if ion[i] is None or ion[j] is None or affinity[i] is None or affinity[j] is None:
            continue
        hi = ion[i] - affinity[i]
        hj = ion[j] - affinity[j]
        if hi <= 0 or hj <= 0:
            continue
        w = occ[i] * occ[j] * (max(0.0, 1.35 - d / (radii[i] + radii[j])) / 0.35) ** 2
        delta = 0.5 * (ion[i] + affinity[i] - ion[j] - affinity[j])
        total += w * delta * delta / (hi + hj)
    return float(total / amount)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    edges = [(a.get('i'), a.get('j'), a.get('distance_A') or 0.0) for a in s.get('neighbors') or []]
    valid = [(i, j, d) for i, j, d in edges if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d > 0 and occ[j] > 0]
    total = 0.0
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    for i in range(n):
        if occ[i] <= 0:
            continue
        shell = [(j, d) for ii, j, d in valid if ii == i]
        if not shell:
            continue
        nearest = min(d for j, d in shell)
        weights = [(occ[j], (max(0.0, 1.5 - d / nearest) / 0.5) ** 2) for j, d in shell if d < 1.5 * nearest]
        first = sum(o * w for o, w in weights)
        second = sum(o * w * w for o, w in weights)
        if second > 0:
            total += occ[i] * first * first / second
    return float(total / amount)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        overlap = max(0.0, 1.0 - d / (radii[i] + radii[j]))
        total += occ[i] * occ[j] * overlap ** 4
    return float(total / amount)

