@0 n="covalent_packing_fraction" d="Occupied covalent-sphere volume divided by unit-cell volume." B=699
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    total = 0.0
    sphere = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        total += o
        r = (props.get(t.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            sphere += o * r * r * r
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * total
    if volume <= 0:
        return 0.0
    return 4.1887902047863905 * sphere / volume
@end
@1 n="smooth_contact_coordination" d="Occupied mean effective coordination using contact weight 1/(1+(distance/radius_sum)^6)." B=848
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                total += occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
    return total / atoms
@end
@2 n="ionic_contact_burden" d="Smooth-contact ionic-character burden per occupied atom, counting each pair once." B=1148
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    result = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and en[i] is not None and en[j] is not None:
                x = d / (a + b)
                x2 = x * x
                w = occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
                delta = en[i] - en[j]
                character = 1.0 - float(np.exp(-0.25 * delta * delta))
                result += w * character
