                total += occ[i]
    if total <= 0:
        return 0.0
    return result / total"},{"description":"Smooth-contact unlike-element fraction minus its random-mixing expectation from occupied site fractions.","name":"heterochemical_contact_excess","source":"def feature(s):
    if not s:
