    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    same = sum(occ[i] * occ[j] for i in range(n) for j in range(n) if elements[i] == elements[j]) / (atoms * atoms)
    total = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                w = occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
                total += w
                if elements[i] != elements[j]:
                    unlike += w
    if total <= 0:
        return 0.0
    return unlike / total - (1.0 - same)"},{"description":"Contact-weighted squared Mulliken electronegativity difference divided by summed neutral-atom hardness, per occupied atom.","name":"contact_hardness_scaled_electronic_contrast","source":"def feature(s):
    if not s:
