    props = s.get('element_properties') or {}
    total = 0.0
    sphere = 0.0
    for t in sites:
        o = max(0.0, t.get('occupancy', 1.0) or 0.0)
        total += o
        r = (props.get(t.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            sphere += o * r * r * r
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * total
    if volume <= 0:
        return 0.0
    return 4.1887902047863905 * sphere / volume"},{"description":"Occupied mean effective coordination using contact weight 1/(1+(distance/radius_sum)^6).","name":"smooth_contact_coordination","source":"def feature(s):
