                character = 1.0 - float(np.exp(-0.25 * delta * delta))
                result += w * character
    return 0.5 * result / atoms"},{"description":"Contact-weighted minimum neutral-atom electron-transfer gap IE(donor)-EA(acceptor), in eV, over unlike-element contacts.","name":"contact_neutral_transfer_gap","source":"def feature(s):
