            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                w = occ[i] * occ[j] / (1.0 + x ** 6)
                contrast = (a - b) / (a + b)
                result += w * contrast * contrast
                total += w
    if total <= 0:
        return 0.0
    return result / total"},{"description":"Log-one-plus occupancy-weighted quartic covalent-overlap burden per atom, counting each pair once.","name":"quartic_contact_overlap_burden","source":"def feature(s):
